const data = $json;

const execution = data.execution || {};
const trigger = data.trigger || {};
const error = execution.error || trigger.error || {};

const workflowName = data.workflow?.name || 'Unknown Workflow';
const workflowId = data.workflow?.id || 'Unknown';

const executionId = execution.id || '';
const executionUrl = execution.url || '';

const failedNode =
  execution.lastNodeExecuted ||
  error.node?.name ||
  'Unknown Node';

const errorMessage =
  error.message ||
  error.cause?.message ||
  'Unknown error';

const errorStack =
  error.stack ||
  error.cause?.stack ||
  '';

const failureMode =
  execution.mode ||
  trigger.mode ||
  'unknown';

let failedAt = new Date().toISOString();

if (error.timestamp) {
  failedAt = new Date(error.timestamp).toISOString();
}

return {
  json: {
    workflow_name: workflowName,
    workflow_id: workflowId,
    execution_id: executionId,
    execution_url: executionUrl,
    failed_node: failedNode,
    error_message: errorMessage,
    error_stack: errorStack,
    failure_mode: failureMode,
    failed_at: failedAt
  }
};
